const THEME_NAMES = ["Original","Violet","Emerald","Amber","Rose"]
const THEMED = {"bat0.png":1,"bat1.png":1,"bat2.png":1,"bat3.png":1,"bat4.png":1,"bat5.png":1,"bat6.png":1,"bat7.png":1,"bat8.png":1,"bat9.png":1,"cdisc0.png":1,"col0.png":1,"deg0.png":1,"font_12_0.png":1,"font_12_1.png":1,"font_12_2.png":1,"font_12_3.png":1,"font_12_4.png":1,"font_12_5.png":1,"font_12_6.png":1,"font_12_7.png":1,"font_12_8.png":1,"font_12_9.png":1,"font_13_0.png":1,"font_13_1.png":1,"font_13_2.png":1,"font_13_3.png":1,"font_13_4.png":1,"font_13_5.png":1,"font_13_6.png":1,"font_13_7.png":1,"font_13_8.png":1,"font_13_9.png":1,"font_3_0.png":1,"font_3_1.png":1,"font_3_2.png":1,"font_3_3.png":1,"font_3_4.png":1,"font_3_5.png":1,"font_3_6.png":1,"font_3_7.png":1,"font_3_8.png":1,"font_3_9.png":1,"neg0.png":1,"pct0.png":1,"strip/s0.png":1,"sunrise.png":1,"sunset.png":1,"ticks/t0.png":1}
