// ---- saved choices (theme / variant): survive a restart and reach the always-on screen ----
const dcGet = (k) => {
  try { const v = Number(zosFs.readFileSync({ path: 'dc_' + k + '.txt', options: { encoding: 'utf8' } })); if (v) return v } catch (e) {}
  try { if (typeof hmFS !== 'undefined') return Number(hmFS.SysProGetInt(k)) || 0 } catch (e) {}
  return 0
}
const dcSet = (k, v) => {
  try { zosFs.writeFileSync({ path: 'dc_' + k + '.txt', data: String(v), options: { encoding: 'utf8' } }) } catch (e) {}
  try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt(k, v) } catch (e) {}
}

WatchFace({
  initView() {
    // the picked colour theme survives a restart (when the watch offers storage)
    themeIdx = dcGet('dialcraft_theme') % THEME_NAMES.length

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    let gen = 0
    const made = []
    const mk = (t, o) => { const w = ui.createWidget(t, o); made.push(w); return w }
    const mkH = (h, t, o) => { const w = h.createWidget(t, o); made.push(w); return w }
    // a timer or sensor callback of an old build must not touch its deleted widgets
    const guard = (f, g) => (...a) => { if (g === gen) return f(...a) }
    const buildFace = () => {
      const g = ++gen
      initArrays()
      let sun_0, sun_1, sun_2, sun_3   // layers shown by the hour or the sun; unset when their choice is not on screen
      // Background (FILL_RECT)
      mk(ui.widget.FILL_RECT, {
        x: px(0),
        y: px(0),
        w: px(390),
        h: px(450),
        color: 0x000000,
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Dial AOD (IMG)
      mk(ui.widget.IMG, {
        x: px(0),
        y: px(0),
        src: A('dial-aod-half.png'),
        show_level: ui.show_level.ONLY_AOD
      })

      // Ticks (IMG)
      mk(ui.widget.IMG, {
        x: px(0),
        y: px(0),
        src: A('ticks/t0.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Hour AOD (IMG_TIME)
      mk(ui.widget.IMG_TIME, {
        hour_startX: px(13),
        hour_startY: px(128),
        hour_zero: 1,
        hour_space: px(0),
        hour_align: ui.align.LEFT,
        hour_array: img_Hour_AOD_j6c2,
        hour_follow: 0,
        show_level: ui.show_level.ONLY_AOD,
      })

      // Minute (IMG_TIME) — normal state
      mk(ui.widget.IMG_TIME, {
        minute_startX: px(13),
        minute_startY: px(229),
        minute_zero: 1,
        minute_space: px(0),
        minute_align: ui.align.LEFT,
        minute_array: img_Minute_njh0,
        minute_follow: 0,
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Minute (IMG_TIME) — AOD (screen-off)
      mk(ui.widget.IMG_TIME, {
        minute_startX: px(13),
        minute_startY: px(229),
        minute_zero: 1,
        minute_space: px(0),
        minute_align: ui.align.LEFT,
        minute_array: img_Minute_njh0,
        minute_follow: 0,
        show_level: ui.show_level.ONLY_AOD,
      })

      // Seconds reel (IMG)
      W.reel = mk(ui.widget.IMG, {
        x: px(182),
        y: px(175),
        w: px(54),
        h: px(100),
        pos_y: px(-1116),
        src: A('strip/s0.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Reel fade top (IMG)
      mk(ui.widget.IMG, {
        x: px(182),
        y: px(175),
        src: A('fade-top.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Reel fade bottom (IMG)
      mk(ui.widget.IMG, {
        x: px(182),
        y: px(241),
        src: A('fade-bot.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Tap pad (IMG)
      mk(ui.widget.IMG, {
        x: px(0),
        y: px(0),
        w: px(1),
        h: px(1),
        src: A('tap.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Hour (IMG_TIME)
      mk(ui.widget.IMG_TIME, {
        hour_startX: px(13),
        hour_startY: px(128),
        hour_zero: 1,
        hour_space: px(0),
        hour_align: ui.align.LEFT,
        hour_array: img_Hour_14id,
        hour_follow: 0,
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Badge temp (IMG)
      mk(ui.widget.IMG, {
        x: px(268),
        y: px(40),
        src: A('cdisc0.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Badge sun (IMG)
      mk(ui.widget.IMG, {
        x: px(298),
        y: px(168),
        src: A('cdisc0.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Badge battery disc (IMG)
      mk(ui.widget.IMG, {
        x: px(278),
        y: px(296),
        src: A('cdisc0.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Tap temperature (IMG_CLICK)
      mk(ui.widget.IMG_CLICK, {
        x: px(266),
        y: px(40),
        w: px(92),
        h: px(114),
        src: A('tapzone-b.png'),
        type: ui.data_type.WEATHER_CURRENT,
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Tap sun (IMG_CLICK)
      mk(ui.widget.IMG_CLICK, {
        x: px(296),
        y: px(168),
        w: px(92),
        h: px(114),
        src: A('tapzone-b.png'),
        type: ui.data_type.SUN_CURRENT,
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Tap battery (TAP)
      mk(ui.widget.BUTTON, {
        x: px(276), y: px(296), w: px(92), h: px(114),
        text: '',
        normal_src: A('tapzone.png'),
        press_src: A('tapzone.png'),
        click_func: () => { if (typeof hmApp !== 'undefined') hmApp.startApp({ url: "Settings_batteryManagerScreen", native: true }) },
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Sunrise icon (IMG)
      sun_0 = mk(ui.widget.IMG, {
        x: px(325),
        y: px(195),
        src: A('sunrise.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Sunset icon (IMG)
      sun_1 = mk(ui.widget.IMG, {
        x: px(325),
        y: px(195),
        src: A('sunset.png'),
        show_level: ui.show_level.ONLY_NORMAL
      })

      // Battery level (IMG_LEVEL)
      mk(ui.widget.IMG_LEVEL, {
        x: px(305),
        y: px(323),
        image_array: img_Battery_level_t18g,
        image_length: img_Battery_level_t18g.length,
        type: ui.data_type.BATTERY,
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Weather icon (IMG_LEVEL)
      mk(ui.widget.IMG_LEVEL, {
        x: px(295),
        y: px(67),
        image_array: img_Weather_icon_on01,
        image_length: img_Weather_icon_on01.length,
        type: ui.data_type.WEATHER,
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Temperature (TEXT_IMG)
      mk(ui.widget.TEXT_IMG, {
        x: px(278),
        y: px(125),
        type: ui.data_type.WEATHER_CURRENT,
        font_array: img_Temperature_0000,
        h_space: px(-4),
        align_h: ui.align.CENTER_H,
        unit_en: A('deg0.png'),
        unit_sc: A('deg0.png'),
        unit_tc: A('deg0.png'),
        negative_image: A('neg0.png'),
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Sunrise (TEXT_IMG)
      sun_2 = mk(ui.widget.TEXT_IMG, {
        x: px(291),
        y: px(253),
        type: ui.data_type.SUN_RISE,
        font_array: img_Sunrise_0000,
        h_space: px(-4),
        align_h: ui.align.CENTER_H,
        dot_image: A('col0.png'),
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Sunset (TEXT_IMG)
      sun_3 = mk(ui.widget.TEXT_IMG, {
        x: px(291),
        y: px(253),
        type: ui.data_type.SUN_SET,
        font_array: img_Sunrise_0000,
        h_space: px(-4),
        align_h: ui.align.CENTER_H,
        dot_image: A('col0.png'),
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Battery (TEXT_IMG)
      mk(ui.widget.TEXT_IMG, {
        x: px(284),
        y: px(381),
        type: ui.data_type.BATTERY,
        font_array: img_Sunrise_0000,
        h_space: px(-4),
        align_h: ui.align.CENTER_H,
        unit_en: A('pct0.png'),
        unit_sc: A('pct0.png'),
        unit_tc: A('pct0.png'),
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Tap: next colour theme (TAP)
      mk(ui.widget.BUTTON, {
        x: px(172), y: px(155), w: px(90), h: px(140),
        text: '',
        normal_src: A('tapzone.png'),
        press_src: A('tapzone.png'),
        click_func: () => { cycleTheme() },
        show_level: ui.show_level.ONLY_NORMAL,
      })

      // Sunrise / sunset swap. The watch has no "next sunrise" reading: SUN_CURRENT stays on today's sunset once it has passed.
      // So the plain SUN_RISE and SUN_SET readings sit in the same place and this shows the one that comes next:
      // the sunset from sunrise until sunset, the sunrise otherwise (after sunset it is today's sunrise time, within a minute or two of tomorrow's).
      const sunClock = new Time()
      const sunTimes = () => {   // today's [sunrise, sunset] in minutes since midnight, from the weather data; null when the watch has none
        try {
          const WeatherCls = zosSensors && zosSensors.Weather
          const wx = WeatherCls ? new WeatherCls() : null
          const f = wx ? (wx.getForecastWeather ? wx.getForecastWeather() : wx.getForecast()) : null
          const t = f && f.tideData && f.tideData.data && f.tideData.data[0]
          if (t && t.sunrise && t.sunset) return [t.sunrise.hour * 60 + t.sunrise.minute, t.sunset.hour * 60 + t.sunset.minute]
        } catch (e) {}
        return null
      }
      const updateSun = () => {
        const m = sunClock.getHours() * 60 + sunClock.getMinutes()
        const t = sunTimes() || [360, 1080]   // without weather data: 06:00 to 18:00 counts as day
        const nextIsSunset = m >= t[0] && m < t[1]
        if (sun_0) sun_0.setProperty(ui.prop.VISIBLE, !nextIsSunset)
        if (sun_1) sun_1.setProperty(ui.prop.VISIBLE, nextIsSunset)
        if (sun_2) sun_2.setProperty(ui.prop.VISIBLE, !nextIsSunset)
        if (sun_3) sun_3.setProperty(ui.prop.VISIBLE, nextIsSunset)
      }
      updateSun()
      sunClock.onPerMinute(guard(updateSun, g))
      mk(ui.widget.WIDGET_DELEGATE, { resume_call: updateSun })
    }
    const rebuild = () => {
      for (const w of made) { try { if (ui.deleteWidget) ui.deleteWidget(w); else if (typeof hmUI !== 'undefined') hmUI.deleteWidget(w) } catch (e) {} }
      made.length = 0
      buildFace()
    }
    // a Tap zone calls this; the rebuild runs after the tap handler returns (it deletes the tap zone itself)
    const cycleTheme = () => {
      themeIdx = (themeIdx + 1) % THEME_NAMES.length
      dcSet('dialcraft_theme', themeIdx)
      try { if (typeof hmUI !== 'undefined' && hmUI.showToast) hmUI.showToast({ text: THEME_NAMES[themeIdx] }) } catch (e) {}
      if (typeof setTimeout === 'function') setTimeout(rebuild, 0); else rebuild()
    }
    buildFace()

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      // the seconds scroll: one tall strip pushed down inside its box with pos_y, 20 times a second (a picture swap would reset the box, so the window size is sent every time)
      const OFF = 50 - 22, WIN = { w: pxv(54), h: pxv(100) };
      const tick = () => {
        const d = new Date();
        const t = d.getSeconds() + d.getMilliseconds() / 1000, s = Math.floor(t);
        W.reel.setProperty(ui.prop.MORE, { w: WIN.w, h: WIN.h, pos_y: Math.round(OFF - (62 - s) * 44 + (t - s) * 44) });
      };
      // a colour-theme switch rebuilds the whole face and runs this block again: keep one timer and one screen-on/off delegate for the whole session
      const G = globalThis;
      try { if (G.__halfTm) clearInterval(G.__halfTm); } catch (e) {}
      G.__halfTick = tick;
      const start = () => { try { if (G.__halfTm) clearInterval(G.__halfTm); } catch (e) {} G.__halfTick(); G.__halfTm = setInterval(() => G.__halfTick(), 50); };
      const stop = () => { try { if (G.__halfTm) clearInterval(G.__halfTm); } catch (e) {} G.__halfTm = 0; };
      start();
      if (!G.__halfDel) { G.__halfDel = 1; ui.createWidget(ui.widget.WIDGET_DELEGATE, { pause_call: stop, resume_call: start }); }
    }
  },

  build() {
    this.initView()
  },
})
